// Des: Judge one reply: good, gone, block or thin shell, with per-site rules
// Flo: status > PDF good > convert to UTF-8 > validate > extra block phrases, min text, must-have phrases, required JSON fields > shell check > verdict
// I/O: Got + previous row + merged Conf (caller) > Judg
// ===================================================================
const std = @import("std"); const mem = std.mem; const vali = @import("sc-reco-vali.zig"); const chrs = @import("pa-char-dete.zig"); const html = @import("pa-html-text.zig"); const inde = @import("st-page-inde.zig"); const pipe = @import("ru-page-fetc.zig"); const shel = @import("pa-shel-dete.zig"); const trap = @import("pa-trap-dete.zig"); const cfgz = @import("cf-conf-load.zig");
pub const Judg = enum { good, gone, block, shel };
fn hasAny(text: []const u8, list: []const []const u8) bool { for (list) |item| { if (std.ascii.findIgnoreCase(text, item) != null) return true; } return false; }
fn hasAll(text: []const u8, list: []const []const u8) bool { for (list) |item| { if (std.ascii.findIgnoreCase(text, item) == null) return false; } return true; }
pub fn judgPage(aren: std.mem.Allocator, got: pipe.Got, prev: ?inde.Row, conf: cfgz.Conf) !Judg { if (got.code == 304 and prev != null) return .good; if (got.code == 404 or got.code == 410) return .gone; if (got.code >= 200 and got.code < 300) { if (std.ascii.findIgnoreCase(got.ctyp, "application/pdf") != null) return .good; const utf8 = chrs.utf8Conv(aren, chrs.charFind(got.ctyp, got.body), got.body) catch return .block; const verd = vali.pageVali(aren, got.ctyp, utf8) catch .bloc; if (verd == .bloc or verd == .jbad) return .block; const jsnz = std.ascii.findIgnoreCase(got.ctyp, "json") != null; if (jsnz) { if (conf.judg_fiel_requ.len > 0) { if ((try trap.poisChek(aren, utf8, conf.judg_fiel_requ)) != null) return .block; } return if (verd == .okay) .good else .block; } if (conf.judg_bloc_list.len > 0 or conf.judg_must_list.len > 0 or conf.judg_text_minz > 0) { const text = try html.htmlText(aren, utf8); if (hasAny(text, conf.judg_bloc_list)) return .block; if (text.len < conf.judg_text_minz) return .block; if (!hasAll(text, conf.judg_must_list)) return .block; } if (shel.shelChek(aren, utf8, conf.shel_text_minz, conf.shel_mark_list) catch false) return .shel; return if (verd == .okay) .good else .block; } if (got.code == 401 or got.code == 403 or got.code == 429 or got.code == 503) return .block; return .gone; }
